class Solution:
    def minScore(self, n: int, roads: List[List[int]]) -> int:
        graph = defaultdict(dict)
        for a, b, d in roads:
            graph[a][b] = graph[b][a] = d

        q = deque()
        q.append((1, 0))
        visited_edges = set()
        while q:
            node, min_score = q.popleft()
            if node == n:
                return min_score
            for adj, d in graph[node].items():
                edge = tuple(sorted((node, adj)))
                if edge not in visited_edges:
                    q.append((adj, min(min_score, d)))
                    visited_edges.add(edge)
